btn.className = "meal-name-suggestion-use";
btn.dataset.uid = recipe.uid || "";
btn.textContent = __fhT("text.use_this_instead", "Use this instead?");
row.appendChild(label);
row.appendChild(btn);
list.appendChild(row);
