// People for the Right Now bar: the household members (Settings > Users), each with their own
// calendar(s) - like "Also for" - so a shared calendar such as Holidays isn't a "person". Falls back
// to the calendar columns when nobody's been linked to a calendar yet.
_rightNowPeople() {
const settings = this._getSettings();
const people = this._getPeople();
const colorMap = this._colorByName(people);
const byEntity = {};
people.forEach((p) => {
if (p && p.entity) byEntity[p.entity] = p;
});
const memberIds = Array.isArray(settings.memberUserIds) ? settings.memberUserIds : [];
const profiles = settings.userProfiles || {};
const names = this._householdMemberNamesById || {};
const out = [];
const seen = new Set();
memberIds.forEach((uid) => {
const profile = profiles[uid] || {};
const entity = profile.primaryCalendar;
if (!entity || !byEntity[entity] || seen.has(entity)) return;
seen.add(entity);
const column = byEntity[entity];
const extras = Array.isArray(profile.extraCalendars) ? profile.extraCalendars.filter((e) => typeof e === "string" && e && e !== entity) : [];
out.push({
entity,
userId: uid,
name: names[uid] || column.name || entity,
color: profile.color || this._colorFor(column, colorMap),
badges: Array.isArray(column.badges) ? column.badges : [],
extraEntities: Array.from(new Set([...(Array.isArray(column.extraEntities) ? column.extraEntities : []), ...extras])),
});
});
if (out.length) return out;
return people.filter((p) => p && p.entity);
}
