if (remindersField) remindersField.style.display = kiosk ? "none" : "";
const listsToggle = root.querySelector('.accordion-toggle[data-target="notify-profile-lists-body"]');
const listsField = listsToggle && listsToggle.closest(".field");
if (listsField) listsField.style.display = kiosk ? "none" : "";
