if (!name) {
this._showToast(__fhT("text.type_a_name_for_the_block_first", "Type a name for the block first."), true);
return;
}
const modeBtn = root.querySelector(".mb-mode-btn.active");
const recurring = !!(modeBtn && modeBtn.dataset.mode === "recurring");
