color: (p.colorLockedToProfile !== false && primaryColors[p.entity]) || p.color || palette[i % palette.length],
colorLockedToProfile: p.colorLockedToProfile !== false,
countdown: !!p.countdown,
badges: primaryBadges[p.entity] || (Array.isArray(p.badges) ? p.badges : []),
// that person's own individual Reminders to-do list entity (separate from the shared family list)
remindersEntity: primaryReminders[p.entity] || (typeof p.remindersEntity === "string" ? p.remindersEntity : ""),
// see _primaryCalendarAdditionalRemindersByEntity - only ever comes from a profile
additionalRemindersEntities: primaryAdditionalReminders[p.entity] || [],
