entity,
name: names[uid] || uid,
color: profile.color || palette[people.length % palette.length],
// A freshly synthesized column is, by construction, a calendar that was JUST assigned to this profile (nothing else could have created it)
colorLockedToProfile: true,
countdown: false,
badges: Array.isArray(profile.badges) ? profile.badges : [],
remindersEntity: typeof profile.remindersEntity === "string" ? profile.remindersEntity : "",
