// Child/Kiosk account type - merged into one mutually-exclusive pair (household ask: "you can either be one, or the other").
root.querySelectorAll(".notify-profile-account-type-btn").forEach((btn) => {
btn.addEventListener("click", () => {
const userId = this._notifyProfileEditingUserId;
if (userId === undefined || userId === null) return;
const profile = this._settingsUserProfilesDraft[userId];
const value = btn.dataset.value;
const turningOn = !btn.classList.contains("active");
if (value === "child") {
profile.isChildAccount = turningOn;
if (turningOn) profile.isKioskAccount = false;
} else {
profile.isKioskAccount = turningOn;
if (turningOn) profile.isChildAccount = false;
if (turningOn) {
profile.isAlarmKiosk = true;
root.querySelectorAll(".notify-profile-alarm-kiosk-btn").forEach((b) => b.classList.toggle("active", b.dataset.value === "on"));
if (!Array.isArray(this._settingsKioskLoginUserIdsDraft)) this._settingsKioskLoginUserIdsDraft = [];
if (!this._settingsKioskLoginUserIdsDraft.includes(userId)) this._settingsKioskLoginUserIdsDraft.push(userId);
const kioskLoginCheckEl = root.querySelector(".notify-profile-kiosk-login-check");
if (kioskLoginCheckEl) kioskLoginCheckEl.checked = true;
}
}
root.querySelectorAll(".notify-profile-account-type-btn").forEach((b) => {
b.classList.toggle("active", (b.dataset.value === "child" && profile.isChildAccount) || (b.dataset.value === "kiosk" && profile.isKioskAccount));
});
this._applyKioskProfileUi(profile);
});
});
