// (calendar UX review) helpers for Settings > Calendars.
_calendarFriendlyName(entity) {
const state = entity && this._hass && this._hass.states && this._hass.states[entity];
const friendly = state && state.attributes && state.attributes.friendly_name;
return (typeof friendly === "string" && friendly.trim()) || entity || "";
}
// The Name a calendar row gets automatically: Home Assistant's name, cut
// at a word boundary to fit the Name box's 20-character limit.
_calendarAutoName(entity) {
let name = this._calendarFriendlyName(entity);
if (name.length > 20) {
const cut = name.slice(0, 20);
const lastSpace = cut.lastIndexOf(" ");
name = (lastSpace > 8 ? cut.slice(0, lastSpace) : cut).trim();
}
return name;
}
// <option>s for one calendar row's picker: every calendar.* entity Home Assistant has, by name, minus the ones another row already uses.
_calendarEntityOptionsHtml(current, list, idx) {
const esc = (v) => String(v || "").replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
const used = new Set((Array.isArray(list) ? list : []).filter((p, i) => i !== idx && p && p.entity).map((p) => p.entity));
const states = (this._hass && this._hass.states) || {};
const entities = Object.keys(states)
.filter((e) => e.startsWith("calendar.") && (e === current || !used.has(e)))
.sort((a, b) => this._calendarFriendlyName(a).localeCompare(this._calendarFriendlyName(b)));
if (current && !entities.includes(current)) entities.unshift(current);
const placeholder = `<option value="" ${current ? "" : "selected"}>${esc(this._t("settings.choose_calendar", "Choose a calendar…"))}</option>`;
return (
placeholder +
entities
.map((e) => {
const label = states[e] ? this._calendarFriendlyName(e) : `${e} (${this._t("settings.calendar_not_found", "not found")})`;
return `<option value="${esc(e)}" ${e === current ? "selected" : ""}>${esc(label)}</option>`;
})
.join("")
);
}
// The rows Settings > Calendars edits: every calendar column (_getPeople)
_peopleDraftForSettings() {
const people = this._getPeople().concat(this._holidayCalendarRows || []);
const listed = new Set(people.map((p) => p && p.entity).filter(Boolean));
const settings = this._getSettings() || {};
const savedRows = Array.isArray(settings.people) ? settings.people : [];
const profiles = settings.userProfiles || {};
const palette = ["#a9c6c2", "#dba99c", "#d9bf7e", "#a8bd93", "#b9a7c9", "#cf8f6c", "#a89a83"];
Object.keys(profiles)
.sort()
.forEach((uid) => {
const extras = (profiles[uid] && Array.isArray(profiles[uid].extraCalendars) && profiles[uid].extraCalendars) || [];
extras.forEach((entity) => {
if (!entity || listed.has(entity)) return;
listed.add(entity);
const saved = savedRows.find((r) => r && r.entity === entity) || {};
people.push({
entity,
name: saved.name || this._calendarAutoName(entity),
color: saved.color || palette[people.length % palette.length],
colorLockedToProfile: saved.colorLockedToProfile !== false,
countdown: !!saved.countdown,
badges: Array.isArray(saved.badges) ? saved.badges : [],
remindersEntity: typeof saved.remindersEntity === "string" ? saved.remindersEntity : "",
additionalRemindersEntities: [],
extraEntities: [],
});
});
});
return people;
}
// each calendar's own color from Home Assistant (2026.2+ keeps one per calendar; the Google integration fills it from Google).
async _fetchHaCalendarColors() {
if (!this._hass || !this._hass.connection || !this._hass.connection.sendMessagePromise) return {};
try {
const res = await this._hass.connection.sendMessagePromise({ type: "family_hub/calendar/colors" });
this._haCalendarColors = (res && res.colors) || {};
} catch (e) {
this._haCalendarColors = this._haCalendarColors || {};
}
return this._haCalendarColors;
}
_haCalendarColor(entity) {
const c = entity && this._haCalendarColors ? this._haCalendarColors[entity] : "";
return typeof c === "string" && /^#[0-9a-f]{6}$/i.test(c) ? c.toLowerCase() : "";
}
_closeCalendarColorMenu() {
if (this._calendarColorMenuEl) {
this._calendarColorMenuEl.remove();
this._calendarColorMenuEl = null;
}
if (this._calendarColorMenuOff) {
this._root.removeEventListener("click", this._calendarColorMenuOff, true);
this._calendarColorMenuOff = null;
}
}
// Tap a calendar's color: choose a color (the browser's picker), or reset
// it to the calendar's own color from Home Assistant/Google.
_openCalendarColorMenu(swatch) {
const wrap = swatch.parentElement;
const already = this._calendarColorMenuEl && this._calendarColorMenuEl.parentElement === wrap;
this._closeCalendarColorMenu();
if (already) return;
const input = wrap.querySelector(".person-color");
const idx = parseInt(swatch.dataset.idx, 10);
const row = swatch.closest(".person-row");
const entitySel = row && row.querySelector(".person-entity");
const entity = entitySel ? entitySel.value : "";
const ha = this._haCalendarColor(entity);
const esc = (v) => String(v || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");
const menu = document.createElement("div");
menu.className = "person-color-pop";
menu.innerHTML =
`<button type="button" class="pcp-pick">&#127912; ${esc(this._t("settings.calendar_color_choose", "Choose a color…"))}</button>` +
(ha
? `<button type="button" class="pcp-reset"${ha === String(input.value).toLowerCase() ? ' disabled style="opacity:.55;cursor:default"' : ""}><span class="pcp-dot" style="background:${ha}"></span>&#8634; ${esc(this._t("settings.calendar_color_reset", "Reset to calendar color"))}</button>`
: `<div class="pcp-note">${esc(entity ? this._t("settings.calendar_color_none", "This calendar has no color of its own in Home Assistant.") : this._t("settings.calendar_color_pick_first", "Pick a calendar first."))}</div>`);
wrap.appendChild(menu);
this._calendarColorMenuEl = menu;
menu.addEventListener("click", (e) => e.stopPropagation());
menu.querySelector(".pcp-pick").addEventListener("click", () => {
this._closeCalendarColorMenu();
try {
if (typeof input.showPicker === "function") input.showPicker();
else input.click();
} catch (err) {
input.click();
}
});
const reset = menu.querySelector(".pcp-reset");
if (reset) {
reset.addEventListener("click", () => {
input.value = ha;
swatch.style.background = ha;
this._syncPeopleDraftFromDom();
if (this._settingsPeopleDraft[idx]) {
this._settingsPeopleDraft[idx].color = ha;
this._settingsPeopleDraft[idx].colorLockedToProfile = false;
}
this._closeCalendarColorMenu();
});
}
this._calendarColorMenuOff = (e) => {
if (!menu.contains(e.target) && e.target !== swatch) this._closeCalendarColorMenu();
};
this._root.addEventListener("click", this._calendarColorMenuOff, true);
}
// "+ Add calendar": a blank row with a color nobody else is using yet.
_addCalendarRowToDraft() {
this._syncPeopleDraftFromDom();
const palette = ["#a9c6c2", "#dba99c", "#d9bf7e", "#a8bd93", "#b9a7c9", "#cf8f6c", "#a89a83"];
const usedColors = new Set(this._settingsPeopleDraft.map((p) => String((p && p.color) || "").toLowerCase()));
const color = palette.find((c) => !usedColors.has(c)) || palette[this._settingsPeopleDraft.length % palette.length];
this._settingsPeopleDraft.push({ entity: "", name: "", color, countdown: false, badges: [] });
this._renderPeopleSettings(this._settingsPeopleDraft);
const pickers = this._root.querySelectorAll("select.person-entity");
const last = pickers[pickers.length - 1];
if (last) {
if (typeof last.scrollIntoView === "function") last.scrollIntoView({ block: "center" });
if (typeof last.focus === "function") last.focus();
}
}
// Opens Settings straight onto General > Calendars (expanded).
