_collapseLongHints(root) {
const scope = root || this._root;
if (!scope || !scope.querySelectorAll) return;
scope.querySelectorAll(".remind-hint").forEach((hint) => {
// Whether this hint is already wrapped has to be read from the DOM itself (a .remind-hint-text child), not a dataset flag
if (!hint.querySelector(".remind-hint-text")) {
const text = hint.textContent;
if (!text || !text.trim()) return;
const textSpan = document.createElement("span");
textSpan.className = "remind-hint-text";
while (hint.firstChild) textSpan.appendChild(hint.firstChild);
const toggleBtn = document.createElement("button");
toggleBtn.type = "button";
toggleBtn.className = "remind-hint-toggle-btn";
toggleBtn.textContent = "i";
toggleBtn.title = this._t("settings.hint_show_tip", "Show tip");
toggleBtn.addEventListener("click", () => {
hint.classList.toggle("expanded");
});
hint.appendChild(textSpan);
hint.appendChild(toggleBtn);
}
const textSpan = hint.querySelector(".remind-hint-text");
if (!textSpan) return;
// Drop has-overflow before measuring, not after - while it's set, CSS hides .remind-hint-text entirely
hint.classList.remove("has-overflow");
// Same "no real stylesheet cascade in this environment" guard as the screensaver-widget portal code above
if (typeof getComputedStyle !== "function") return;
const lineHeight = parseFloat(getComputedStyle(textSpan).lineHeight) || 14;
const twoLines = lineHeight * 2 + 1;
const overflows = textSpan.scrollHeight > twoLines;
hint.classList.toggle("has-overflow", overflows);
if (!overflows) hint.classList.remove("expanded");
});
}
