// Best-effort clipboard write with a fallback for contexts where navigator.clipboard either doesn't exist or throws (an insecure context
async _copyTextToClipboard(text) {
// window.navigator, not bare navigator - same reasoning as window.
if (window.navigator && window.navigator.clipboard && window.navigator.clipboard.writeText) {
try {
await window.navigator.clipboard.writeText(text);
return;
} catch (e) {
// fall through to the textarea approach below
}
}
const textarea = document.createElement("textarea");
textarea.value = text;
textarea.style.position = "fixed";
textarea.style.opacity = "0";
document.body.appendChild(textarea);
textarea.focus();
textarea.select();
let ok = false;
try {
ok = document.execCommand("copy");
} catch (e) {
ok = false;
}
document.body.removeChild(textarea);
if (!ok) throw new Error("copy command failed");
}
