if (!entity || !byEntity[entity] || seen.has(entity)) return;
const extras = Array.isArray(profile.extraCalendars) ? profile.extraCalendars : [];
if (entity === ownEntity || extras.includes(ownEntity)) return;
seen.add(entity);
