// Show/hide the interval, weekday-picker and ends-condition fields to match whichever frequency/end-condition button is currently active
_updateAddEventRecurVisibility() {
const root = this._root;
const freqBtn = root.querySelector(".add-event-recur-freq-btn.active");
const freq = freqBtn ? freqBtn.dataset.value : "none";
const repeats = freq !== "none";
root.querySelector(".add-event-recur-interval-field").style.display = repeats ? "" : "none";
root.querySelector(".add-event-recur-weekdays-field").style.display = freq === "WEEKLY" ? "" : "none";
root.querySelector(".add-event-recur-end-field").style.display = repeats ? "" : "none";
const unitLabels = { DAILY: "day(s)", WEEKLY: "week(s)", MONTHLY: "month(s)", YEARLY: "year(s)" };
const unitEl = root.querySelector(".add-event-recur-interval-unit");
if (unitEl) unitEl.textContent = unitLabels[freq] || "";
const endBtn = root.querySelector(".add-event-recur-end-btn.active");
const endMode = endBtn ? endBtn.dataset.value : "never";
root.querySelector(".add-event-recur-end-date-field").style.display = repeats && endMode === "on" ? "" : "none";
root.querySelector(".add-event-recur-end-count-field").style.display = repeats && endMode === "after" ? "" : "none";
}
// Builds an RFC 5545 RRULE value string (no "RRULE:" prefix - that's added, if at all
_buildRecurRrule(allDay) {
const root = this._root;
const freqBtn = root.querySelector(".add-event-recur-freq-btn.active");
const freq = freqBtn ? freqBtn.dataset.value : "none";
if (freq === "none") return null;
const parts = [`FREQ=${freq}`];
const interval = parseInt(root.querySelector(".add-event-recur-interval").value, 10);
if (Number.isFinite(interval) && interval > 1) parts.push(`INTERVAL=${interval}`);
if (freq === "WEEKLY") {
const days = this._readRolldaysFromContainer(root.querySelector(".add-event-recur-weekdays"));
if (days.length) parts.push(`BYDAY=${days.map((d) => RRULE_WEEKDAY_CODES[d]).join(",")}`);
}
const endBtn = root.querySelector(".add-event-recur-end-btn.active");
const endMode = endBtn ? endBtn.dataset.value : "never";
if (endMode === "on") {
const endDateVal = root.querySelector(".add-event-recur-end-date").value;
if (endDateVal) {
// Same value type as DTSTART, per RFC 5545 - an all-day event's UNTIL is a bare date (YYYYMMDD)
if (allDay) {
parts.push(`UNTIL=${endDateVal.replace(/-/g, "")}`);
} else {
const untilLocal = new Date(`${endDateVal}T23:59:59`);
const untilUtc = untilLocal.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
parts.push(`UNTIL=${untilUtc}`);
}
}
} else if (endMode === "after") {
const count = parseInt(root.querySelector(".add-event-recur-end-count").value, 10);
if (Number.isFinite(count) && count > 0) parts.push(`COUNT=${count}`);
}
return parts.join(";");
}
_formatReminderMinutes(minutes) {
if (minutes % 1440 === 0) {
const days = minutes / 1440;
return `${days} day${days > 1 ? "s" : ""}`;
}
if (minutes % 60 === 0) {
const hours = minutes / 60;
return `${hours} hour${hours > 1 ? "s" : ""}`;
}
return `${minutes} minutes`;
}
_formatReminderLabel(minutesList) {
const list = Array.isArray(minutesList) ? minutesList : [minutesList];
if (!list.length) return "";
return `${list.map((m) => this._formatReminderMinutes(m)).join(" & ")} before`;
}
// shared by both _saveAddEvent's calendar branch and _saveAddReminder below - reads whatever's currently set in the checklist section
